-- Homepage: the single "Featured project" panel becomes an auto-sliding
-- Feature carousel (new builder block) of the lab's projects and recent blog
-- articles, each with its own image. Previous layout kept as a page revision.

INSERT INTO public.cms_page_revisions (page_id, title, content, seo, reason)
SELECT id, title || ' (before featured carousel)', published_content, seo, 'publish'
FROM public.cms_pages
WHERE slug = ''
  AND published_content->'sections'->3->>'id' = 'xdin8sjix'
  AND content->'sections'->3->>'id' = 'xdin8sjix'
  AND published_content->'sections'->3->'children'->0->>'id' = 'x4fw96kda';

